static const float GLOBAL_MEAN = -74.596161f;
// binary search (table is sorted by bssid)
inline float ap_mean_rssi(const char* bssid) {
  int lo=0, hi=N_AP-1;
  while (lo<=hi){ int mid=(lo+hi)/2; int c=strcmp(bssid,ap_table[mid].bssid);
    if (c==0) return ap_table[mid].mean; if (c<0) hi=mid-1; else lo=mid+1; }
  return GLOBAL_MEAN;
}

// Returns predicted RSSI in dBm for the given location and AP mean.
inline double predictRSSI(double x, double y, int floor_id, int building_num_, double ap_mean_rssi_){
  double feats[5] = {x, y, (double)floor_id, (double)building_num_, ap_mean_rssi_};
  int node = 0;
  while (left[node] != -1) {
    if (feats[feature[node]] <= threshold[node]) node = left[node];
    else node = right[node];
  }
  return value[node];
}

// Configurable coverage thresholds (dBm). Editable for deployment.
static const double TH_EXCELLENT = -50.0;
static const double TH_GOOD = -60.0;
static const double TH_FAIR = -70.0;
static const double TH_POOR = -80.0;
static const double TH_VERY_POOR = -999.0;
// returns 5=Excellent,4=Good,3=Fair,2=Poor,1=VeryPoor,0=Unknown
inline int coverageClass(double rssi){
  if (rssi >= TH_EXCELLENT) return 5;
  if (rssi >= TH_GOOD) return 4;
  if (rssi >= TH_FAIR) return 3;
  if (rssi >= TH_POOR) return 2;
  if (rssi >= TH_VERY_POOR) return 1;
  return 0;
}
